  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B035",
        "laureates": [
          "Hidetoshi Katori",
          "Jun Ye"
        ],
        "citation": "For the invention and realization of optical lattice clocks, enabling unprecedented precision in timekeeping and tests of fundamental physics."
      }
    ]
  },
  "alternatives": [
    "B018",
    "B017"
  ],
  "statement": {
    "case_for": "My configuration is unchanged: I continue to favor B035. Independent implementations, sustained improvements, and demonstrated use in precision measurement make optical lattice clocks a mature experimental achievement. Katori and Ye represent complementary foundational contributions. The citation should stay with the invention and realization of lattice clocks, with tests of fundamental physics indicating their reach rather than expanding the claim to the whole history of optical clocks.",
    "case_against": "The central remaining difficulty is historical attribution: the foundational contributions must be distinguished from later enabling advances across a broad field. A precise instrument alone is not sufficient; the case rests on the lasting measurement capability and demonstrated scientific use it opened.",
    "responses": [
      {
        "member_id": "johansson-goran",
        "point": "Johansson favors circuit QED for establishing a new, controllable light–matter regime, while recognizing the maturity of optical lattice clocks and questioning where their foundational scope ends.",
        "response": "I agree that circuit QED has a strong case based on an experimentally established regime, and that the clock citation needs a careful boundary. I retain B035 because the independent clock implementations and sustained gains demonstrate a reliable method for precision measurement. The scope should remain the lattice-clock invention and realization, not every subsequent advance in optical clocks."
      },
      {
        "member_id": "olsson-eva",
        "point": "Olsson favors recognizing Katori and Ye for optical lattice clocks, while emphasizing the need to distinguish their foundational contributions from later demonstrations and advances.",
        "response": "That distinction is central to my attribution as well. The independent foundational approaches support credit to both, while later demonstrations establish the method's maturity and reach. They should not be folded into the achievement in a way that obscures who made the original contributions; the precise division should be settled by historical review."
      }
    ],
    "uncertainties": [
      "Historical evidence is needed to separate Katori's and Ye's foundational contributions from later enabling demonstrations and to represent their respective roles accurately.",
      "The extent to which demonstrated tests of fundamental physics, alongside timekeeping, should shape the concise citation needs review."
    ],
    "conflict_note": "My profile notes an institutional overlap between my WACQT executive role and Johansson's Chalmers affiliation. I know of no direct connection to B035 or its proposed laureates."
  }
}
